async function applyStyleToCellParagraphs(cells, styleName, context) {
  cells.forEach(cell => cell.load("body"));
  await context.sync();

  cells.forEach(cell => {
    const paragraphs = cell.body.paragraphs;
    paragraphs.load("items");
  });
  await context.sync();

  cells.forEach(cell => {
    cell.body.paragraphs.items.forEach(paragraph => {
      paragraph.style = styleName;
    });
  });
  await context.sync();
}

/**
 * Updates all fields in the main body of the document in controlled batches.
 * Adjusts the batch size based on the document's complexity and API limits.
 * todo: may be able to also filter by label such as Table, Figure, so only updates affected
 * versus all SEQ fields
 */
async function updateAllFieldsInBatches(fieldType = "Seq") {
  await Word.run(async (context) => {
    const batchSize = 50;
    let totalUpdated = 0;

    // Helper to update fields in a given range
    async function updateFieldsInRange(range, label) {
      const fields = range.fields;
      fields.load("items, type");
      await context.sync();

      const matchingFields = fields.items.filter((field) => field.type === fieldType);
      if (matchingFields.length > 0) {
        console.log(`Updating ${matchingFields.length} ${label} fields in batches...`);
        for (let i = 0; i < matchingFields.length; i += batchSize) {
          const batchEnd = Math.min(i + batchSize, matchingFields.length);
          for (let j = i; j < batchEnd; j++) {
            matchingFields[j].updateResult();
          }
          await context.sync();
        }
        totalUpdated += matchingFields.length;
      }
    }

    // Update fields in the main body
    await updateFieldsInRange(context.document.body, "body");

    // Update fields in all headers across sections
    const sections = context.document.sections;
    sections.load("items");
    await context.sync();

    for (const section of sections.items) {
      const headers = [
        section.getHeader("Primary"),
        section.getHeader("FirstPage"),
        section.getHeader("EvenPages"),
      ];
      for (const header of headers) {
        await updateFieldsInRange(header, "header");
      }
    }

    console.log(`Finished updating ${totalUpdated} fields total.`);
  });
}



