// todo: this doesn't really seem to work very well. may work if 
async function getCurrentSection(context) {
  const selection = context.document.getSelection();
  const sections = context.document.sections;
  sections.load("items");
  await context.sync();

  for (let section of sections.items) {
    const range = section.body.getRange("Whole");
    await context.sync();

    const startsAfter = selection.compareLocationWith(range, Word.LocationRelation.after);
    const endsBefore = selection.compareLocationWith(range, Word.LocationRelation.before);
    await context.sync();

    if (!startsAfter && !endsBefore) {
      return section;
    }
  }

  throw new Error("Current section not found.");
}

async function getSectionIndexFromSelection() {
  return await Word.run(async (context) => {
    const selection = context.document.getSelection();
    const selectionRange = selection.getRange();
    selectionRange.load("text");

    const sections = context.document.sections;
    sections.load("items");

    await context.sync();

    for (let i = 0; i < sections.items.length; i++) {
      const sectionBodyRange = sections.items[i].body.getRange();
      sectionBodyRange.load("text");

      await context.sync();

      const location = selectionRange.compareLocationWith(sectionBodyRange);

      await context.sync();

      if (location.value ===  Word.LocationRelation.inside || location.value === Word.LocationRelation.equal) {
        console.log(`Selection is in section ${i}`);
        return i;
      }
    }

    console.log("Selection not found in any section.");
    return -1;
  });
}

