async function getCustomPropertiesAsJson(propertyNames) {
    return Word.run(async (context) => {
        const props = context.document.properties.customProperties;
        context.load(props);
      //  props.load("items");
        await context.sync();

        const result = {};
        for (const name of propertyNames) {
            const match = props.items.find(p => p.key === name);
            result[name] = match ? match.value : null;
        }

        return result;
    });
}

async function setCustomPropertiesFromJson(propertyDict) {
    return Word.run(async (context) => {
        const props = context.document.properties.customProperties;
        props.load("items");
        await context.sync();

        for (const [key, value] of Object.entries(propertyDict)) {
            const existing = props.items.find(p => p.key === key);
            if (existing) {
                existing.value = String(value ?? ""); // Update existing
            } else {
                props.add(key, String(value ?? "")); // Add new
            }
        }

        await context.sync();
    });
}



/**
 * Todo: not used but was trying out since Word Online doesn't support custom properties.
 * Sets or updates a property in the document's settings.
 * This is a reliable alternative for Word Online where custom properties can fail.
 *
 * @param {string} name - The name of the property.
 * @param {any} value - The value to set for the property.
 */
async function setDocumentSetting(name, value) {
  // Check if Office.context and settings are available before proceeding.
  if (!Office || !Office.context || !Office.context.document || !Office.context.document.settings) {
    console.error("Office context or settings not available.");
    return;
  }

  // The `settings.set()` method automatically adds or updates the value in the in-memory copy.
  // There is no need to check for the property's existence first, unlike with custom properties.
  Office.context.document.settings.set(name, String(value ?? ""));

  // The `saveAsync` method is used to persist the changes to the document.
  // It is a separate asynchronous call with a callback to handle the result.
  Office.context.document.settings.saveAsync(asyncResult => {
    if (asyncResult.status === Office.AsyncResultStatus.Succeeded) {
      console.log(`Setting "${name}" successfully saved.`);
    } else {
      console.error(`Error saving setting "${name}":`, asyncResult.error.message);
    }
  });
}

async function getDocumentSetting(key) {
  return new Promise((resolve, reject) => {
    Office.context.document.settings.refreshAsync(function (refreshResult) {
      if (refreshResult.status === Office.AsyncResultStatus.Succeeded) {
        const value = Office.context.document.settings.get(key);
        resolve(value);
      } else {
        reject(new Error(`Failed to refresh settings: ${refreshResult.error.message}`));
      }
    });
  });
}

