export async function convertContentXmlToSettings(size: number) {

    // magoo. get the content xml and save it to the settings.
    let  xmlDoc = await getAutoTextXmlFromContentXml();

    // build a dictionary of snippets
    const snippets = xmlDoc.querySelectorAll("Snippet");
    const snippetMap = {};

    snippets.forEach(snippetNode => {
      const id = snippetNode.getAttribute("id");
      if (id) {
         snippetMap[id] = snippetNode.textContent;
      }
    });

    // loop through saving to settings.
    for (const [id, value] of Object.entries(snippetMap)) {
        let autoTextId = "autotext_" + id;
        await setDocumentSetting(autoTextId, value);
        let settingsValue = await getDocumentSetting(autoTextId);
        console.log("settings: " + settingsValue);
    }

    console.log("conversion to settings complete.")

}


function getLocalizedLongDate() {
    const locale = "en-AU";
    const now = new Date();

    return now.toLocaleDateString(locale, {
        day: "numeric",
        month: "long",
        year: "numeric"
    });
}


